    conn = sqlite3.connect(MAP_PATH)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    tile_data = {}
    for row in cur.execute("SELECT * FROM Plots"):
        pid = row['ID']
        x, y = pid % WIDTH, pid // WIDTH
        tt = row['TerrainType']
        terrain, is_hills, is_mountain = parse_terrain(tt)
        tile_data[(x, y)] = {
            'terrain': 'MOUNTAIN' if is_mountain else terrain,
            'is_hills': is_hills,
            'feature': None,
            'is_floodplains': False,
            'river_edges': [],
            'resource': None,
            'resource_type': None,
            'improvement': None,
        }

    for row in cur.execute("SELECT * FROM PlotFeatures"):
        pid = row['ID']
        x, y = pid % WIDTH, pid // WIDTH
        if (x, y) in tile_data:
            feat = row['FeatureType']
            tile_data[(x, y)]['feature'] = feat
            if 'FLOODPLAINS' in feat:
                tile_data[(x, y)]['is_floodplains'] = True

    for row in cur.execute("SELECT * FROM PlotResources"):
        pid = row['ID']
        x, y = pid % WIDTH, pid // WIDTH
        if (x, y) in tile_data:
            tile_data[(x, y)]['resource'] = row['ResourceType']

    # Rivers: mark both plots sharing each river edge
    for row in cur.execute("SELECT * FROM PlotRivers"):
        pid = row['ID']
        x, y = pid % WIDTH, pid // WIDTH
        if row['IsNEOfRiver'] or row['IsWOfRiver'] or row['IsNWOfRiver']:
            if (x, y) in tile_data:
                tile_data[(x, y)]['river_edges'].append(0)
        if row['IsNEOfRiver']:
            if y % 2 == 0:
                nb = (x, y + 1)
            else:
                nb = (x + 1, y + 1)
            if nb in tile_data:
                tile_data[nb]['river_edges'].append(1)
        if row['IsWOfRiver']:
            nb = (x - 1, y)
            if nb in tile_data:
                tile_data[nb]['river_edges'].append(2)
        if row['IsNWOfRiver']:
            if y % 2 == 0:
                nb = (x - 1, y + 1)
            else:
                nb = (x, y + 1)
            if nb in tile_data:
                tile_data[nb]['river_edges'].append(3)

    tiles = {}
    for (x, y), d in tile_data.items():
        tiles[(x, y)] = Tile(
            x=x, y=y, terrain=d['terrain'],
            feature=d['feature'], is_hills=d['is_hills'],
            is_floodplains=d['is_floodplains'],
            river_edges=d['river_edges'],
            resource=d['resource'],
            resource_type=d['resource_type'],
            improvement=d['improvement'],
        )
    conn.close()
    return tiles


def main():
    tiles = load_tiles()
    city_center = (21, 13)
    population = 9

    rules = get_placement_rules(tiles, city_center, population)
    calc = get_adjacency_calculator(tiles)

    workable = [(x, y) for (x, y) in get_tiles_in_range(*city_center, 3)
                if (x, y) in tiles]

    print(f"City center: {city_center} tile: {tiles[city_center].terrain}, feat={tiles[city_center].feature}, river={bool(tiles[city_center].river_edges)}")
    print("Workable tiles:")
    for (x, y) in workable:
        t = tiles[(x, y)]
        print(f"  ({x},{y}) {t.terrain} hills={t.is_hills} feat={t.feature} river={bool(t.river_edges)}")
    print()

    specialty_options = [
        DistrictType.CAMPUS,
        DistrictType.HOLY_SITE,
        DistrictType.THEATER_SQUARE,
        DistrictType.COMMERCIAL_HUB,
        DistrictType.HARBOR,
        DistrictType.INDUSTRIAL_ZONE,
        DistrictType.GOVERNMENT_PLAZA,
    ]
    max_specialty = rules.max_specialty_districts()
    print(f"Max specialty districts: {max_specialty}")

    existing = {city_center: DistrictType.CITY_CENTER}

    def valid_tiles_for(dt, placement):
        occupied = set(placement.keys())
        valid = []
        for (x, y) in workable:
            if (x, y) in occupied:
                continue
            if rules.validate_placement(dt, x, y, placement).valid:
                valid.append((x, y))
        return valid

    for dt in specialty_options + [DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL]:
        cs = valid_tiles_for(dt, existing)
        print(f"{dt.name}: {len(cs)} candidate tiles -> {cs[:10]}")

    def greedy_search(district_set):
        best_local_total = -1
        best_local_placement = None

        orderings = list(permutations(district_set))
        if len(orderings) > 24:
            orderings = orderings[:24]

        for order in orderings:
            placement = {city_center: DistrictType.CITY_CENTER}
            feasible = True
            for dt in order:
                cands = valid_tiles_for(dt, placement)
                if not cands:
                    feasible = False
                    break
                best_pos = None
                best_total_tmp = -10**9
                for pos in cands:
                    trial = dict(placement)
                    trial[pos] = dt
                    tot, _ = calc.calculate_total_adjacency(trial)
                    if tot > best_total_tmp:
                        best_total_tmp = tot
                        best_pos = pos
                placement[best_pos] = dt
            if not feasible:
                continue
            tot, _ = calc.calculate_total_adjacency(placement)

            improved = True
            iters = 0
            while improved and iters < 30:
                improved = False
                iters += 1
                for pos, dt in list(placement.items()):
                    if dt == DistrictType.CITY_CENTER:
                        continue
                    trial_base = {p: d for p, d in placement.items() if p != pos}
                    cands = valid_tiles_for(dt, trial_base)
                    for new_pos in cands:
                        if new_pos == pos:
                            continue
                        trial = dict(trial_base)
                        trial[new_pos] = dt
                        new_tot, _ = calc.calculate_total_adjacency(trial)
                        if new_tot > tot:
                            placement = trial
                            tot = new_tot
                            improved = True
                            break
                    if improved:
                        break

            if tot > best_local_total:
                best_local_total = tot
                best_local_placement = placement

        return best_local_total, best_local_placement

    best_total = -1
    best_placement = None

    specialty_combos = list(combinations(specialty_options, max_specialty))

    for combo in specialty_combos:
        tot, pl = greedy_search(list(combo))
        if tot > best_total:
            best_total = tot
            best_placement = pl
            print(f"  New best (specialty {[d.name for d in combo]}): {tot}")

    print("\nTrying to augment with non-specialty districts...")
    for extra_dt in [DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL]:
        cands = valid_tiles_for(extra_dt, best_placement)
        if not cands:
            continue
        best_extra_tot = best_total
        best_extra_pos = None
        for pos in cands:
            trial = dict(best_placement)
            trial[pos] = extra_dt
            tot, _ = calc.calculate_total_adjacency(trial)
            if tot > best_extra_tot:
                best_extra_tot = tot
                best_extra_pos = pos
        if best_extra_pos:
            best_placement[best_extra_pos] = extra_dt
            best_total = best_extra_tot
            print(f"  Added {extra_dt.name} at {best_extra_pos}, new total: {best_total}")

    print("\nSecond pass: specialty + AQUEDUCT combos (joint)...")
    for combo in specialty_combos:
        for extras in [[DistrictType.AQUEDUCT], [DistrictType.CANAL], [DistrictType.AQUEDUCT, DistrictType.CANAL]]:
            combo_list = list(combo) + extras
            tot, pl = greedy_search(combo_list)
            if tot > best_total:
                best_total = tot
                best_placement = pl
                print(f"  New best (+{[d.name for d in extras]} {[d.name for d in combo]}): {tot}")

    best_total, best_per = calc.calculate_total_adjacency(best_placement)
    print(f"\nFinal best total: {best_total}")
    print("Final placement:")
    for pos, dt in best_placement.items():
        print(f"  {dt.name} at {pos}")
    print("Breakdown:")
    for key, r in best_per.items():
        print(f"  {key}: {r.total_bonus} - {r.breakdown}")

    placements_out = {}
    bonuses_out = {}
    for pos, dt in best_placement.items():
        if dt == DistrictType.CITY_CENTER:
            continue
        placements_out[dt.name] = list(pos)
    for key, r in best_per.items():
        dname = key.split('@')[0]
        bonuses_out[dname] = r.total_bonus

    output = {
        "city_center": list(city_center),
        "placements": placements_out,
        "adjacency_bonuses": bonuses_out,
        "total_adjacency": best_total,
    }
    with open('/output/scenario_3.json', 'w') as f:
        json.dump(output, f, indent=2)
    print("\nWritten /output/scenario_3.json")
    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
